RegisterBankInfo::PartialMapping AIE2PGenRegisterBankInfo::PartMappings[]{
    // StartIdx, Length, RegBank
    // 0: GPR 32-bit value
    {0, 32, AIE2P::GPRRegBank},
    // 1: PTR 20-bit value
    {0, 20, AIE2P::PTRRegBank},
    // 2: MOD 20-bit value
    {0, 20, AIE2P::MODRegBank},
    // 3(PMI_CB)
    {},
    // 4: GPR 64-bit value
    {0, 64, AIE2P::GPRRegBank},
    // 5(undef),6(undef)
    {},
    {},
    // 7: VREG 256-bit value
    {0, 256, AIE2P::VRegBank},
    // 8: VREG 512-bit value
    {0, 512, AIE2P::VRegBank},
    // 9: VREG 1024-bit value
    {0, 1024, AIE2P::VRegBank},
    // 10: AccREG 256-bit value
    {},
    // 11: AccREG 512-bit value
    {0, 512, AIE2P::AccRegBank},
    // 12: AccREG 1024-bit value
    {0, 1024, AIE2P::AccRegBank},
    // 13: VREG 128-bit value
    {0, 128, AIE2P::VRegBank},
    // 14: AccREG 2048-bit value
    {0, 2048, AIE2P::AccRegBank},
    // 15: FifoREG 512-bit value
    {0, 512, AIE2P::FifoRegBank},
    // 16: FifoREG 1024-bit value
    {0, 1024, AIE2P::FifoRegBank},
};

// ValueMappings.
RegisterBankInfo::ValueMapping AIE2PGenRegisterBankInfo::ValMappings[]{
    /* BreakDown, NumBreakDowns */
    // 0: invalid
    {nullptr, 0},
    // 3-operands instructions
    // 1: GPR 32-bit value. <-- This must match First3OpsIdx.
    {&PartMappings[PMI_GPR - PMI_Min], 1},
    {&PartMappings[PMI_GPR - PMI_Min], 1},
    {&PartMappings[PMI_GPR - PMI_Min], 1},
    // 4: PTR 20-bit value.
    {&PartMappings[PMI_PTR - PMI_Min], 1},
    {&PartMappings[PMI_PTR - PMI_Min], 1},
    {&PartMappings[PMI_PTR - PMI_Min], 1},
    // 7: MOD 20-bit value. <-- This must match Last3OpsIdx
    {&PartMappings[PMI_MOD - PMI_Min], 1},
    {&PartMappings[PMI_MOD - PMI_Min], 1},
    {&PartMappings[PMI_MOD - PMI_Min], 1},
    // 10: AIE1's CB:
    {},
    {},
    {},
    // 13: GPR 64-bit value.
    {&PartMappings[PMI_GPR64 - PMI_Min], 1},
    {&PartMappings[PMI_GPR64 - PMI_Min], 1},
    {&PartMappings[PMI_GPR64 - PMI_Min], 1},
    // 16:
    {&PartMappings[PMI_VREG256 - PMI_Min], 1},
    {&PartMappings[PMI_VREG256 - PMI_Min], 1},
    {&PartMappings[PMI_VREG256 - PMI_Min], 1},
    // 19:
    {&PartMappings[PMI_VREG512 - PMI_Min], 1},
    {&PartMappings[PMI_VREG512 - PMI_Min], 1},
    {&PartMappings[PMI_VREG512 - PMI_Min], 1},
    // 22:
    {&PartMappings[PMI_VREG1024 - PMI_Min], 1},
    {&PartMappings[PMI_VREG1024 - PMI_Min], 1},
    {&PartMappings[PMI_VREG1024 - PMI_Min], 1},
    // 25: AIE2's ACC256:
    {},
    // 26:
    {&PartMappings[PMI_ACC512 - PMI_Min], 1},
    // 27:
    {&PartMappings[PMI_ACC1024 - PMI_Min], 1},
    // 28:
    {&PartMappings[PMI_VREG128 - PMI_Min], 1},
    // 29:
    {&PartMappings[PMI_ACC2048 - PMI_Min], 1},
    // 30:
    {&PartMappings[PMI_FIFO512 - PMI_Min], 1},
    {&PartMappings[PMI_FIFO1024 - PMI_Min], 1},
};

const RegisterBankInfo::ValueMapping *
AIE2PGenRegisterBankInfo::getValueMapping(PartialMappingIdx RBIdx,
                                          unsigned Size) const {
  assert(RBIdx != PartialMappingIdx::PMI_None && "No mapping needed for that");
  unsigned BaseIdxOffset = getRegBankBaseIdxOffset(RBIdx, Size);
  if (BaseIdxOffset == -1u)
    return &ValMappings[InvalidIdx];

  unsigned ValMappingIdx;
  PartialMappingIdx PMIdx;
  ValueMappingIdx VMIdx = ValueMappingIdx::First3OpsIdx;
  ValueMappingIdx DistRegBanks = ValueMappingIdx::DistanceBetweenRegBanks;
  switch (RBIdx) {
  case PMI_GPR:
  case PMI_PTR:
  case PMI_MOD:
  case PMI_GPR64:
    PMIdx = PartialMappingIdx::PMI_Min;
    break;
  case PMI_VREG128:
    PMIdx = PartialMappingIdx::PMI_VREG128;
    VMIdx = ValueMappingIdx::S128_Idx;
    break;
  case PMI_VREG256:
  case PMI_VREG512:
  case PMI_VREG1024:
    PMIdx = PartialMappingIdx::PMI_VREGMin;
    VMIdx = ValueMappingIdx::FirstVecOpsIdx;
    break;
  case PMI_ACC512:
  case PMI_ACC1024:
  case PMI_ACC2048:
    PMIdx = PartialMappingIdx::PMI_ACC512;
    DistRegBanks = ValueMappingIdx::DistanceBetweenAccRegBanks;
    VMIdx = ValueMappingIdx::FirstAccOpsIdx;
    break;
  case PMI_FIFO512:
  case PMI_FIFO1024:
    PMIdx = PartialMappingIdx::PMI_FIFO512;
    VMIdx = ValueMappingIdx::FirstFifoOpsIdx;
    DistRegBanks = ValueMappingIdx::DistanceBetweenFifoRegBanks;
    break;
  default:
    llvm_unreachable("Unsupported PartialMappingIdx.");
  }
  ValMappingIdx = VMIdx + (RBIdx - PMIdx + BaseIdxOffset) * DistRegBanks;
  assert(ValMappingIdx >= First3OpsIdx && ValMappingIdx <= LastOpsIdx &&
         "Mapping out of bound");
  return &ValMappings[ValMappingIdx];
}

AIEBaseRegisterBankInfo::PartialMappingIdx
AIE2PGenRegisterBankInfo::getPartialMappingIdx(const LLT &Ty) const {
  // in aie2p 2048-bit sized type is an accumulator.
  if (Ty.getSizeInBits() == 2048)
    return PMI_ACC2048;
  // in aie2p 256-bit sized type is a vector.
  if (Ty.getSizeInBits() == 256)
    return PMI_VREG256;
  return AIEBaseRegisterBankInfo::getPartialMappingIdx(Ty);
}

AIEBaseRegisterBankInfo::PartialMappingIdx
AIE2PGenRegisterBankInfo::getAccPartialMappingIdx(const LLT &Ty) const {
  // in aie2p 2048-bit sized type is an accumulator.
  if (Ty.getSizeInBits() == 2048)
    return PMI_ACC2048;
  return AIEBaseRegisterBankInfo::getAccPartialMappingIdx(Ty);
}

AIEBaseRegisterBankInfo::PartialMappingIdx
AIE2PGenRegisterBankInfo::getFifoPartialMappingIdx(const LLT &Ty) const {
  if (Ty.getSizeInBits() == 512)
    return PMI_FIFO512;
  if (Ty.getSizeInBits() == 1024)
    return PMI_FIFO1024;
  llvm_unreachable("Unsupported fifo register size.");
}

AIE2PRegisterBankInfo::AIE2PRegisterBankInfo(const TargetRegisterInfo &TRI)
    : AIE2PGenRegisterBankInfo() {

  static llvm::once_flag InitializeRegisterBankFlag;

  static auto InitializeRegisterBankOnce = [&]() {
    // We have only one set of register banks, whatever the subtarget
    // is. Therefore, the initialization of the RegBanks table should be
    // done only once. Indeed the table of all register banks
    // (AIE2P::RegBanks) is unique in the compiler. At some point, it
    // will get tablegen'ed and the whole constructor becomes empty.

    const RegisterBank &RBGPR = getRegBank(AIE2P::GPRRegBankID);
    (void)RBGPR;
    assert(&AIE2P::GPRRegBank == &RBGPR &&
           "The order in RegBanks is messed up");

    const RegisterBank &RBPTR = getRegBank(AIE2P::PTRRegBankID);
    (void)RBPTR;
    assert(&AIE2P::PTRRegBank == &RBPTR &&
           "The order in RegBanks is messed up");
    const RegisterBank &RBVREG = getRegBank(AIE2P::VRegBankID);
    (void)RBVREG;
    assert(&AIE2P::VRegBank == &RBVREG && "The order in RegBanks is messed up");
    const RegisterBank &RBACCREG = getRegBank(AIE2P::AccRegBankID);
    (void)RBACCREG;
    assert(&AIE2P::AccRegBank == &RBACCREG &&
           "The order in RegBanks is messed up");
    assert(verify(TRI) && "Invalid register bank information");
  };

  llvm::call_once(InitializeRegisterBankFlag, InitializeRegisterBankOnce);
}

static bool isAccReg(const Register Reg) {
  if (Reg.isPhysical() && (AIE2P::ACC512RegClass.contains(Reg) ||
                           AIE2P::ACC1024RegClass.contains(Reg) ||
                           AIE2P::ACC2048RegClass.contains(Reg)))
    return true;
  return false;
}

RegisterBankInfo::InstructionMappings
AIE2PRegisterBankInfo::getInstrAlternativeMappings(
    const MachineInstr &MI) const {
  const MachineFunction &MF = *MI.getParent()->getParent();
  const TargetSubtargetInfo &STI = MF.getSubtarget();
  const TargetRegisterInfo &TRI = *STI.getRegisterInfo();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  switch (MI.getOpcode()) {
  case TargetOpcode::G_LOAD:
  case AIE2P::G_AIE_OFFSET_LOAD:
  case AIE2P::G_AIE_POSTINC_LOAD:
  case AIE2P::G_AIE_POSTINC_2D_LOAD:
  case AIE2P::G_AIE_POSTINC_3D_LOAD: {
    const unsigned NumOperands = MI.getNumOperands();
    const unsigned FirstSrcIdx = MI.getNumExplicitDefs();
    unsigned MappingID = 1;
    unsigned const Cost = 1;

    Register DstReg = MI.getOperand(0).getReg();
    const LLT DstRegTy = MRI.getType(DstReg);
    const unsigned DstSize = getSizeInBits(DstReg, MRI, TRI);

    // Base alternative mapping for sizes up to 256.
    // For 2048-bit sizes, mapping is restricted to the accumulator bank.
    if (DstSize <= 256 || DstSize == 2048)
      break;

    // Prepare the three mapping indices.
    std::vector<AIEBaseRegisterBankInfo::PartialMappingIdx> MappingIndices = {
        getVecPartialMappingIdx(DstRegTy), getAccPartialMappingIdx(DstRegTy),
        getFifoPartialMappingIdx(DstRegTy)};

    // Initialize the operand vectors.
    // Set all operand mapping indices to PMI_MOD by default.
    // Set all operand sizes to 20 by default.
    SmallVector<PartialMappingIdx, 4> OpRegBankIdx(NumOperands, PMI_MOD);
    SmallVector<const ValueMapping *, 8> OpdsMapping(NumOperands);

    for (unsigned I = 1; I < FirstSrcIdx; ++I)
      OpRegBankIdx[I] = (I == 1) ? PMI_PTR : PMI_MOD;

    // Assign PMI_PTR at FirstSrcIdx
    OpRegBankIdx[FirstSrcIdx] = PMI_PTR;

    InstructionMappings AltMappings;
    // For each mapping index in MappingIndices, override operand 0
    // and build an alternative instruction mapping.
    for (const auto &VecIdx : MappingIndices) {
      OpRegBankIdx[0] =
          static_cast<AIEBaseRegisterBankInfo::PartialMappingIdx>(VecIdx);
      for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
        if (MI.getOperand(Idx).isReg() && MI.getOperand(Idx).getReg()) {
          LLT Ty = MRI.getType(MI.getOperand(Idx).getReg());
          if (!Ty.isValid())
            continue;
          OpdsMapping[Idx] =
              getValueMapping(OpRegBankIdx[Idx], (Idx == 0) ? DstSize : 20);
        }
      }
      const InstructionMapping &InsnMapping = getInstructionMapping(
          MappingID++, Cost, getOperandsMapping(OpdsMapping), NumOperands);
      AltMappings.push_back(&InsnMapping);
    }
    return AltMappings;
  }
  case TargetOpcode::G_STORE:
  case AIE2P::G_AIE_OFFSET_STORE:
  case AIE2P::G_AIE_POSTINC_STORE:
  case AIE2P::G_AIE_POSTINC_2D_STORE:
  case AIE2P::G_AIE_POSTINC_3D_STORE: {
    const unsigned NumOperands = MI.getNumOperands();
    // Select the operand index for VecReg.
    const unsigned VecRegOpIdx = MI.getNumExplicitDefs();
    unsigned MappingID = 1;
    unsigned const Cost = 1;

    Register VecReg = MI.getOperand(VecRegOpIdx).getReg();
    const LLT VecRegTy = MRI.getType(VecReg);
    const unsigned VecRegSize = getSizeInBits(VecReg, MRI, TRI);

    // Base alternative mapping for sizes up to 256.
    // For 2048-bit sizes, mapping is restricted to the accumulator bank.
    // Also, if the instruction has any implicit defs/uses, leave it alone.
    if (VecRegSize <= 256 || VecRegSize == 2048 ||
        MI.getNumOperands() != MI.getNumExplicitOperands())
      break;

    // Prepare the three mapping indices.
    std::vector<AIEBaseRegisterBankInfo::PartialMappingIdx> MappingIndices = {
        getVecPartialMappingIdx(VecRegTy), getAccPartialMappingIdx(VecRegTy),
        getFifoPartialMappingIdx(VecRegTy)};

    // Initialize the operand vectors.
    // Set all operand mapping indices to PMI_MOD by default.
    // Set all operand sizes to 20 by default.
    SmallVector<PartialMappingIdx, 4> OpRegBankIdx(NumOperands, PMI_MOD);
    SmallVector<const ValueMapping *, 8> OpdsMapping(NumOperands);

    // Initialize first few indices based on VRegOpIdx
    for (unsigned I = 0; I < VecRegOpIdx; ++I) {
      OpRegBankIdx[I] = (I == 0) ? PMI_PTR : PMI_MOD;
    }

    // Assign PMI_PTR to the next operand if within bounds
    assert(((VecRegOpIdx + 1) < NumOperands) && "RegOpIdx + 1 out of bound");
    OpRegBankIdx[VecRegOpIdx + 1] = PMI_PTR;

    InstructionMappings AltMappings;
    for (const auto &VecIdx : MappingIndices) {
      OpRegBankIdx[VecRegOpIdx] =
          static_cast<AIEBaseRegisterBankInfo::PartialMappingIdx>(VecIdx);
      for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
        if (MI.getOperand(Idx).isReg() && MI.getOperand(Idx).getReg()) {
          LLT Ty = MRI.getType(MI.getOperand(Idx).getReg());
          if (!Ty.isValid())
            continue;
          OpdsMapping[Idx] = getValueMapping(
              OpRegBankIdx[Idx], (Idx == VecRegOpIdx) ? VecRegSize : 20);
        }
      }
      const InstructionMapping &InsnMapping = getInstructionMapping(
          MappingID++, Cost, getOperandsMapping(OpdsMapping), NumOperands);
      AltMappings.push_back(&InsnMapping);
    }
    return AltMappings;
  }
  case TargetOpcode::G_UNMERGE_VALUES: {
    const unsigned NumOperands = MI.getNumOperands();
    assert(NumOperands == 3 &&
           "Unsupported number of operands for G_UNMERGE_VALUES\n");
    const Register SrcReg = MI.getOperand(NumOperands - 1).getReg();
    const LLT SrcTy = MRI.getType(SrcReg);
    unsigned SrcSize = getSizeInBits(SrcReg, MRI, TRI);
    // Only the accumulator is of 2048-bit size, with the possible mapping
    // restricted to accumulator register banks. For a 512-bit vector,
    // the only possible mapping is to a vector register bank.
    if (SrcSize <= 512 || SrcSize == 2048)
      break;
    const LLT HalfSrcTy = SrcTy.divide(2);
    const unsigned HalfSrcTySize = HalfSrcTy.getSizeInBits();
    InstructionMappings AltMappings;
    const InstructionMapping &VRegMapping = getInstructionMapping(
        /*ID*/ 1, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getVecPartialMappingIdx(HalfSrcTy), HalfSrcTySize),
             getValueMapping(getVecPartialMappingIdx(HalfSrcTy), HalfSrcTySize),
             getValueMapping(getVecPartialMappingIdx(SrcTy), SrcSize)}),
        /*NumOperands*/ 3);
    const InstructionMapping &AccRegMapping = getInstructionMapping(
        /*ID*/ 2, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getAccPartialMappingIdx(HalfSrcTy), HalfSrcTySize),
             getValueMapping(getAccPartialMappingIdx(HalfSrcTy), HalfSrcTySize),
             getValueMapping(getAccPartialMappingIdx(SrcTy), SrcSize)}),
        /*NumOperands*/ 3);
    const InstructionMapping &FifoRegMapping = getInstructionMapping(
        /*ID*/ 3, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getFifoPartialMappingIdx(HalfSrcTy),
                             HalfSrcTySize),
             getValueMapping(getFifoPartialMappingIdx(HalfSrcTy),
                             HalfSrcTySize),
             getValueMapping(getFifoPartialMappingIdx(SrcTy), SrcSize)}),
        /*NumOperands*/ 3);

    AltMappings.push_back(&VRegMapping);
    AltMappings.push_back(&AccRegMapping);
    AltMappings.push_back(&FifoRegMapping);
    return AltMappings;
  }
  case TargetOpcode::G_CONCAT_VECTORS: {
    Register DstReg = MI.getOperand(0).getReg();
    const LLT DstTy = MRI.getType(DstReg);
    const LLT HalfDstTy = DstTy.divide(2);
    unsigned DstSize = getSizeInBits(DstReg, MRI, TRI);
    const unsigned HalfDstTySize = HalfDstTy.getSizeInBits();
    // Only the accumulator is of 2048-bit size, with the possible mapping
    // restricted to accumulator register banks. For a 512-bit vector,
    // the only possible mapping is to a vector register bank.
    if (DstSize <= 512 || DstSize == 2048)
      break;

    // If the instruction has any implicit-defs or uses,
    // do not mess with it.
    if (MI.getNumOperands() != 3)
      break;
    InstructionMappings AltMappings;
    const InstructionMapping &VRegMapping = getInstructionMapping(
        /*ID*/ 1, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getVecPartialMappingIdx(DstTy), DstSize),
             getValueMapping(getVecPartialMappingIdx(HalfDstTy), HalfDstTySize),
             getValueMapping(getVecPartialMappingIdx(HalfDstTy),
                             HalfDstTySize)}),
        /*NumOperands*/ 3);
    const InstructionMapping &AccRegMapping = getInstructionMapping(
        /*ID*/ 2, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getAccPartialMappingIdx(DstTy), DstSize),
             getValueMapping(getAccPartialMappingIdx(HalfDstTy), HalfDstTySize),
             getValueMapping(getAccPartialMappingIdx(HalfDstTy),
                             HalfDstTySize)}),
        /*NumOperands*/ 3);
    const InstructionMapping &FifoRegMapping = getInstructionMapping(
        /*ID*/ 3, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getFifoPartialMappingIdx(DstTy), DstSize),
             getValueMapping(getFifoPartialMappingIdx(HalfDstTy),
                             HalfDstTySize),
             getValueMapping(getFifoPartialMappingIdx(HalfDstTy),
                             HalfDstTySize)}),
        /*NumOperands*/ 3);

    AltMappings.push_back(&VRegMapping);
    AltMappings.push_back(&AccRegMapping);
    AltMappings.push_back(&FifoRegMapping);
    return AltMappings;
  }
  case TargetOpcode::G_BITCAST: {
    Register DstReg = MI.getOperand(0).getReg();
    unsigned Size = getSizeInBits(DstReg, MRI, TRI);
    // Only the accumulator is of 2048-bit size, with the possible mapping
    // restricted to accumulator register banks. For a 256-bit vector,
    // the only possible mapping is to a vector register bank.
    if (Size <= 256 || Size == 2048)
      break;

    // If the instruction has any implicit-defs or uses,
    // do not mess with it.
    if (MI.getNumOperands() != 2)
      break;

    InstructionMappings AltMappings;
    const InstructionMapping &VRegMapping = getInstructionMapping(
        /*ID*/ 1, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);
    const InstructionMapping &AccRegMapping = getInstructionMapping(
        /*ID*/ 2, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);
    const InstructionMapping &AccToVRegMapping = getInstructionMapping(
        /*ID*/ 3, /*Cost*/ 2,
        getOperandsMapping(
            {getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);
    const InstructionMapping &VRegToAccRegMapping = getInstructionMapping(
        /*ID*/ 4, /*Cost*/ 2,
        getOperandsMapping(
            {getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);

    AltMappings.push_back(&VRegMapping);
    AltMappings.push_back(&AccRegMapping);
    AltMappings.push_back(&AccToVRegMapping);
    AltMappings.push_back(&VRegToAccRegMapping);
    return AltMappings;
  }
  case TargetOpcode::G_IMPLICIT_DEF: {
    Register DstReg = MI.getOperand(0).getReg();
    unsigned Size = getSizeInBits(DstReg, MRI, TRI);
    // For size 2048, only accumulator register banks are possible.
    // For size <= 256, use base alternative mapping.
    if (Size == 2048 || Size <= 256)
      break;

    InstructionMappings AltMappings;
    const InstructionMapping &VRegMapping = getInstructionMapping(
        /*ID*/ 1, /*Cost*/ 1,
        getOperandsMapping({getValueMapping(
            getVecPartialMappingIdx(MRI.getType(DstReg)), Size)}),
        /*NumOperands*/ 1);
    const InstructionMapping &AccRegMapping = getInstructionMapping(
        /*ID*/ 2, /*Cost*/ 1,
        getOperandsMapping({getValueMapping(
            getAccPartialMappingIdx(MRI.getType(DstReg)), Size)}),
        /*NumOperands*/ 1);

    AltMappings.push_back(&VRegMapping);
    AltMappings.push_back(&AccRegMapping);
    return AltMappings;
  }
  case TargetOpcode::G_TRUNC: {
    Register SrcReg = MI.getOperand(1).getReg();
    LLT SrcTy = MRI.getType(SrcReg);
    if (SrcTy.isVector())
      // TODO : find registerbank using use-def analysis as we do other places.
      return RegisterBankInfo::getInstrAlternativeMappings(MI);
    break;
  }
  default:
    break;
  }
  return AIEBaseRegisterBankInfo::getInstrAlternativeMappings(MI);
}

static bool checkFifoDstSrc(const MachineInstr &MI,
                            const Register &FifoRegCandidate,
                            unsigned DstOpIndex, unsigned SrcOpIndex) {
  Register FifoDstReg = MI.getOperand(DstOpIndex).getReg();
  Register FifoSrcReg = MI.getOperand(SrcOpIndex).getReg();
  return ((FifoRegCandidate == FifoDstReg) || (FifoRegCandidate == FifoSrcReg));
}

// Check if FifoRegCandidate is one of the fifo operands of the intrinsic
static bool isUsedAsFifoRegInIntrinsic(const MachineRegisterInfo &MRI,
                                       const MachineInstr &MI,
                                       const Register FifoRegCandidate) {
  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  // TODO: To be extented with more FIFO using intrinsics
  case Intrinsic::aie2p_fifo_ld_fill: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 5);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_pop_unaligned:
  case Intrinsic::aie2p_fifo_ld_pop_1d_unaligned: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 2, 6);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_pop_544_1d_bfp16:
  case Intrinsic::aie2p_fifo_ld_pop_576_1d_bfp16:
  case Intrinsic::aie2p_fifo_ld_pop_544_bfp16:
  case Intrinsic::aie2p_fifo_ld_pop_576_bfp16: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 7);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_pop_640_unaligned_sparse: {
    // Same shape as 544/576 BFP16: 5 outputs (ptr, fifo, pos, data, mask),
    // intrinsic-id at 5, then ptr=6, fifo=7, pos=8.
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 7);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_pop_2d_unaligned: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 2, 7);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_pop_3d_unaligned: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 2, 8);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_pop_544_2d_bfp16:
  case Intrinsic::aie2p_fifo_ld_pop_576_2d_bfp16: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 8);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_pop_544_3d_bfp16:
  case Intrinsic::aie2p_fifo_ld_pop_576_3d_bfp16: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 9);
    break;
  }
  case Intrinsic::aie2p_fifo_st_push_544_bfp16:
  case Intrinsic::aie2p_fifo_st_push_576_bfp16: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 7);
    break;
  }
  case Intrinsic::aie2p_fifo_st_flush:
  case Intrinsic::aie2p_fifo_st_flush_conv:
  case Intrinsic::aie2p_fifo_st_flush_1d:
  case Intrinsic::aie2p_fifo_st_flush_1d_conv: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 5);
    break;
  }
  case Intrinsic::aie2p_fifo_st_push_512_bfp16:
  case Intrinsic::aie2p_fifo_st_flush_2d:
  case Intrinsic::aie2p_fifo_st_flush_2d_conv: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 6);
    break;
  }
  case Intrinsic::aie2p_fifo_st_flush_3d:
  case Intrinsic::aie2p_fifo_st_flush_3d_conv: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 7);
    break;
  }
  case Intrinsic::aie2p_fifo_ld_fillx: {
    Register FifoExtraDstReg = MI.getOperand(3).getReg();
    Register FifoExtraSrcReg = MI.getOperand(8).getReg();
    return (checkFifoDstSrc(MI, FifoRegCandidate, 1, 6) ||
            (FifoRegCandidate == FifoExtraDstReg) ||
            (FifoRegCandidate == FifoExtraSrcReg));
    break;
  }
  case Intrinsic::aie2p_fifo_ld_popx: {
    Register FifoExtraDstReg = MI.getOperand(4).getReg();
    Register FifoExtraSrcReg = MI.getOperand(9).getReg();
    return (checkFifoDstSrc(MI, FifoRegCandidate, 2, 7) ||
            (FifoRegCandidate == FifoExtraDstReg) ||
            (FifoRegCandidate == FifoExtraSrcReg));
    break;
  }
  default:
    return false;
  }
  return false;
}
/// \returns true if the specified intrinsic has an accumulator
/// vector as one of its operands.
static bool isUsedAsAccRegInIntrinsic(const MachineRegisterInfo &MRI,
                                      const MachineInstr &MI,
                                      const Register AccReg) {
  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  // All Intrinsics with accumulator destination operand
  case Intrinsic::aie2p_vbroadcast_zero_acc1024:
  case Intrinsic::aie2p_scd_expand_ACC1024:
  case Intrinsic::aie2p_scd_ACC2048:
  case Intrinsic::aie2p_scd_expand_ACC1024_incr:
  case Intrinsic::aie2p_scd_expand_ACC2048_incr:
  case Intrinsic::aie2p_scd_expand_ACC2048:
  case Intrinsic::aie2p_scd_expand_lo:
  case Intrinsic::aie2p_scd_expand_hi:
  case Intrinsic::aie2p_scd_read_acc32:
  case Intrinsic::aie2p_acc32_v16_I256_ups:
  case Intrinsic::aie2p_acc32_v32_I256_ups:
  case Intrinsic::aie2p_acc32_v32_I512_ups:
  case Intrinsic::aie2p_acc64_v16_I256_ups:
  case Intrinsic::aie2p_acc64_v16_I512_ups:
  case Intrinsic::aie2p_acc64_v8_I256_ups:
  case Intrinsic::aie2p_acc32_v64_I512_ups:
  case Intrinsic::aie2p_acc64_v32_I512_ups:
  case Intrinsic::aie2p_v8float_to_v16accfloat:
  case Intrinsic::aie2p_v16bf16_to_v16accfloat:
  case Intrinsic::aie2p_v32bf16_to_v32accfloat:
  case Intrinsic::aie2p_v16float_to_v32accfloat:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_bf_mul_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_mul_conf:
  case Intrinsic::aie2p_I1024_I512_ACC2048_mul_conf:
  case Intrinsic::aie2p_I512_I1024_ACC2048_mul_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_bf_mul_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_mul_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_bf_mul_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_mul_conf:
  case Intrinsic::aie2p_I512_I512_ACC512_bf_mul_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_negmul_conf:
  case Intrinsic::aie2p_I1024_I512_ACC2048_negmul_conf:
  case Intrinsic::aie2p_I512_I1024_ACC2048_negmul_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_negmul_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_negmul_conf:
  case Intrinsic::aie2p_I512_I512_ACC512_bf_negmul_conf:
  case Intrinsic::aie2p_BFP576_BFP576_ACC2048_mul_conf:
  case Intrinsic::aie2p_BFP576_BFP576_ACC2048_negmul_conf:
  case Intrinsic::aie2p_BFP576_BFP1152_ACC2048_mul_conf:
  case Intrinsic::aie2p_BFP576_BFP1152_ACC2048_negmul_conf: {
    // Operand at Idx 0 is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    if (AccReg == DstReg)
      return true;
    break;
  }
  // All Intrinsics with first source as accumulator operand
  case Intrinsic::aie2p_mcd_write_acc32: {
    // Operand at Idx 1 is an accumulator operand
    Register SrcReg = MI.getOperand(1).getReg();
    if (AccReg == SrcReg)
      return true;
    break;
  }
  case Intrinsic::aie2p_I256_v16_acc32_srs:
  case Intrinsic::aie2p_I256_v16_acc64_srs:
  case Intrinsic::aie2p_I256_v32_acc32_srs:
  case Intrinsic::aie2p_I256_v8_acc64_srs:
  case Intrinsic::aie2p_I512_v16_acc64_srs:
  case Intrinsic::aie2p_I512_v32_acc32_srs:
  case Intrinsic::aie2p_I512_v32_acc64_srs:
  case Intrinsic::aie2p_I512_v64_acc32_srs:
  case Intrinsic::aie2p_v16accfloat_to_v8float:
  case Intrinsic::aie2p_v16accfloat_to_v16bf16:
  case Intrinsic::aie2p_v32accfloat_to_v32bf16:
  case Intrinsic::aie2p_v32accfloat_to_v16float:
  case Intrinsic::aie2p_exp2:
  case Intrinsic::aie2p_tanh: {
    // Operand at Idx 2 is an accumulator operand
    Register SrcReg = MI.getOperand(2).getReg();
    if (AccReg == SrcReg)
      return true;
    break;
  }
  case Intrinsic::aie2p_ACC2048_sub_conf:
  case Intrinsic::aie2p_ACC2048_accfloat_sub_conf:
  case Intrinsic::aie2p_ACC2048_accfloat_add_conf:
  case Intrinsic::aie2p_ACC2048_add_conf: {
    // Operand at Indices {0, 2, 3} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(2).getReg();
    Register SrcReg1 = MI.getOperand(3).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg0) || (AccReg == SrcReg1))
      return true;
    break;
  }
  case Intrinsic::aie2p_I512_I512_ACC2048_addmac_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2p_I512_I512_ACC512_bf_addmac_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_addmac_conf:
  case Intrinsic::aie2p_I512_I1024_ACC2048_addmac_conf:
  case Intrinsic::aie2p_I1024_I512_ACC2048_addmac_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_addmac_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_addmsc_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2p_I512_I1024_ACC2048_addmsc_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_addmsc_conf:
  case Intrinsic::aie2p_I1024_I512_ACC2048_addmsc_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_addmsc_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2p_I512_I512_ACC512_bf_addmsc_conf: {
    // Operand at Indices {0, 4, 5} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(4).getReg();
    Register SrcReg1 = MI.getOperand(5).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg0) || (AccReg == SrcReg1))
      return true;
    break;
  }
  case Intrinsic::aie2p_I512_I512_ACC512_bf_mac_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_bf_mac_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_mac_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_bf_mac_conf:
  case Intrinsic::aie2p_I512_I1024_ACC2048_mac_conf:
  case Intrinsic::aie2p_I1024_I512_ACC2048_mac_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_mac_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_bf_mac_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_mac_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_bf_msc_conf:
  case Intrinsic::aie2p_I1024_I1024_ACC2048_msc_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_msc_conf:
  case Intrinsic::aie2p_I512_I512_ACC512_bf_msc_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_bf_msc_conf:
  case Intrinsic::aie2p_I512_I512_ACC1024_msc_conf:
  case Intrinsic::aie2p_I512_I512_ACC2048_bf_msc_conf:
  case Intrinsic::aie2p_I512_I1024_ACC2048_msc_conf:
  case Intrinsic::aie2p_I1024_I512_ACC2048_msc_conf: {
    // Operand at Indices {0, 4} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(4).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg0))
      return true;
    break;
  }
  case Intrinsic::aie2p_ACC2048_accfloat_neg_conf:
  case Intrinsic::aie2p_ACC2048_neg_conf: {
    // Operand at Indices {0, 2} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(2).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg0))
      return true;
    break;
  }
  case Intrinsic::aie2p_v64accfloat_to_v64bfp16ebs8:
  case Intrinsic::aie2p_v64accfloat_to_v64bfp16ebs16: {
    // Operand at Index 3 is an accumulator operand
    Register SrcReg = MI.getOperand(3).getReg();
    if (AccReg == SrcReg)
      return true;
    break;
  }
  case Intrinsic::aie2p_BFP576_BFP576_ACC2048_mac_conf:
  case Intrinsic::aie2p_BFP576_BFP576_ACC2048_msc_conf: {
    // Operand at Indices {0, 6} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(6).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg))
      return true;
    break;
  }
  case Intrinsic::aie2p_BFP576_BFP576_ACC2048_addmac_conf:
  case Intrinsic::aie2p_BFP576_BFP576_ACC2048_addmsc_conf: {
    // Operand at Indices {0, 6, 7} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(6).getReg();
    Register SrcReg1 = MI.getOperand(7).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg0) || (AccReg == SrcReg1))
      return true;
    break;
  }
  case Intrinsic::aie2p_BFP576_BFP1152_ACC2048_mac_conf:
  case Intrinsic::aie2p_BFP576_BFP1152_ACC2048_msc_conf: {
    // Operand at Indices {0, 8} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(8).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg))
      return true;
    break;
  }
  case Intrinsic::aie2p_BFP576_BFP1152_ACC2048_addmac_conf:
  case Intrinsic::aie2p_BFP576_BFP1152_ACC2048_addmsc_conf: {
    // Operand at Indices {0, 8, 9} is an accumulator operand
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(8).getReg();
    Register SrcReg1 = MI.getOperand(9).getReg();
    if ((AccReg == DstReg) || (AccReg == SrcReg0) || (AccReg == SrcReg1))
      return true;
    break;
  }
  default:
    return false;
  }
  return false;
}

static bool isUsedAsAccRegInInstr(const MachineInstr &MI,
                                  const MachineRegisterInfo &MRI,
                                  const TargetRegisterInfo &TRI, Register Reg) {
  switch (MI.getOpcode()) {
  default:
    break;
  case TargetOpcode::G_INTRINSIC:
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS:
    return isUsedAsAccRegInIntrinsic(MRI, MI, Reg);
  case TargetOpcode::COPY: {
    Register DstReg = MI.getOperand(0).getReg();
    if (isAccReg(DstReg))
      return true;
    break;
  }
  }
  return false;
}

// Check if the instruction has Reg as a fifo input.
// Similar to usesAccReg for Accumulators
static bool isUsedAsFifoRegInInstr(const MachineInstr &MI,
                                   const MachineRegisterInfo &MRI,
                                   const TargetRegisterInfo &TRI,
                                   Register Reg) {
  const MachineFunction &MF = *MI.getParent()->getParent();
  auto *RI = static_cast<const AIEBaseRegisterInfo *>(
      MF.getSubtarget().getRegisterInfo());
  switch (MI.getOpcode()) {
  default:
    break;
  case TargetOpcode::G_INTRINSIC:
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS:
    return isUsedAsFifoRegInIntrinsic(MRI, MI, Reg);
  case TargetOpcode::COPY: {
    Register DstReg = MI.getOperand(0).getReg();
    if (RI->isFifoPhysReg(DstReg))
      return true;
    break;
  }
  }
  return false;
}

std::optional<const RegisterBank *>
AIE2PRegisterBankInfo::getPreferredRegBankForVectorTy(
    const MachineRegisterInfo &MRI, const TargetRegisterInfo &TRI,
    Register Reg) const {
  LLT RegTy = MRI.getType(Reg);
  TypeSize RegSize = RegTy.getSizeInBits();
  if (RegSize <= 256 && RegSize > 64)
    return &getRegBank(AIE2P::VRegBankID);
  if (RegSize == 2048)
    return &getRegBank(AIE2P::AccRegBankID);

  if (registerBankLookAheadSearch(isUsedAsAccRegInInstr, MRI, TRI, Reg))
    return &getRegBank(AIE2P::AccRegBankID);
  else if (registerBankLookAheadSearch(isUsedAsFifoRegInInstr, MRI, TRI, Reg))
    return &getRegBank(AIE2P::FifoRegBankID);
  else if (RegSize > 64)
    return &getRegBank(AIE2P::VRegBankID);
  return std::nullopt;
}

const RegisterBankInfo::InstructionMapping &
AIE2PRegisterBankInfo::getInstrMapping(const MachineInstr &MI) const {
  const unsigned Opc = MI.getOpcode();

  const MachineFunction &MF = *MI.getParent()->getParent();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  const TargetSubtargetInfo &STI = MF.getSubtarget();
  const TargetRegisterInfo &TRI = *STI.getRegisterInfo();

  const unsigned NumOperands = MI.getNumOperands();
  unsigned Cost = 1;

  // Track the size and bank of each register..
  SmallVector<unsigned, 4> OpSize(NumOperands);
  SmallVector<PartialMappingIdx, 4> OpRegBankIdx(NumOperands);
  switch (Opc) {
  case TargetOpcode::G_INTRINSIC:
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS: {
    // Support special case vshuffle <acc>, xreg, xreg
    if (cast<GIntrinsic>(MI).getIntrinsicID() == Intrinsic::aie2p_vshuffle) {
      // Check if that Intrinsic::aie2p_vshuffle feeds acc instructions.
      Register DstReg = MI.getOperand(0).getReg();
      LLT DstType = MRI.getType(DstReg);
      // Check if we already know the register bank.
      auto *RB = getRegBank(DstReg, MRI, TRI);
      if (RB == &AIE2P::AccRegBank)
        return AIEBaseRegisterBankInfo::getInstrMapping(MI);
      auto PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
      if (PreferredRegBank && &AIE2P::AccRegBank == *PreferredRegBank) {
        OpRegBankIdx[0] = getAccPartialMappingIdx(DstType);
        for (unsigned Idx = 2; Idx < NumOperands; ++Idx) {
          LLT Type = MRI.getType(MI.getOperand(Idx).getReg());
          OpRegBankIdx[Idx] = getPartialMappingIdx(Type);
        }
        return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                             OpRegBankIdx);
      }
    }
    // All other intrinsics
    for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
      const auto &MO = MI.getOperand(Idx);
      if (!MO.isReg() || !MO.getReg())
        continue;
      LLT Ty = MRI.getType(MO.getReg());
      if (!Ty.isValid())
        continue;
      if (isUsedAsAccRegInIntrinsic(MRI, MI, MI.getOperand(Idx).getReg())) {
        LLT Type = MRI.getType(MI.getOperand(Idx).getReg());
        OpRegBankIdx[Idx] = getAccPartialMappingIdx(Type);
        continue;
      }
      if (isUsedAsFifoRegInIntrinsic(MRI, MI, MI.getOperand(Idx).getReg())) {
        LLT Type = MRI.getType(MI.getOperand(Idx).getReg());
        OpRegBankIdx[Idx] = getFifoPartialMappingIdx(Type);
        continue;
      }
      OpRegBankIdx[Idx] = getPartialMappingIdx(MRI.getType(MO.getReg()));
    }
    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  case TargetOpcode::G_IMPLICIT_DEF: {
    // Check if that IMPLICIT_DEF feeds acc instructions.
    Register DstReg = MI.getOperand(0).getReg();
    LLT Type = MRI.getType(DstReg);
    // Check if we already know the register bank.
    auto *RB = getRegBank(DstReg, MRI, TRI);
    if (RB == &AIE2P::AccRegBank)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);
    auto PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
    if (PreferredRegBank && &AIE2P::AccRegBank == *PreferredRegBank) {
      OpRegBankIdx[0] = getAccPartialMappingIdx(Type);
      return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                           OpRegBankIdx);
    } else if (PreferredRegBank && &AIE2P::FifoRegBank == *PreferredRegBank) {
      OpRegBankIdx[0] = getFifoPartialMappingIdx(Type);
      return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                           OpRegBankIdx);
    }
    return AIEBaseRegisterBankInfo::getInstrMapping(MI);
  }
  case TargetOpcode::G_BITCAST: {
    // Check if that G_BITCAST feeds acc instructions.
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(1).getReg();
    LLT DstType = MRI.getType(DstReg);
    LLT SrcType = MRI.getType(SrcReg);
    if (SrcType.getSizeInBits() <= 64)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);
    // Check if we already know the register bank.
    auto *RB = getRegBank(SrcReg, MRI, TRI);
    auto PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
    if ((PreferredRegBank && &AIE2P::AccRegBank == *PreferredRegBank) ||
        (RB == &AIE2P::AccRegBank)) {
      OpRegBankIdx[0] = getAccPartialMappingIdx(DstType);
      OpRegBankIdx[1] = getAccPartialMappingIdx(SrcType);
    } else {
      OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
      OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType);
    }

    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  case TargetOpcode::G_UNMERGE_VALUES: {
    assert(MI.getNumOperands() == 3 &&
           "Unsupported number of operands for G_UNMERGE_VALUES\n");
    const Register SrcReg = MI.getOperand(2).getReg();
    const LLT SrcTy = MRI.getType(SrcReg);
    const LLT HalfSrcTy = SrcTy.divide(2);
    const unsigned HalfSrcTySize = HalfSrcTy.getSizeInBits();
    auto *RB = getRegBank(SrcReg, MRI, TRI);

    if (SrcTy.getSizeInBits() == 2048) {
      return getInstructionMapping(
          /*ID*/ 1, /*Cost*/ 1,
          getOperandsMapping(
              {getValueMapping(getAccPartialMappingIdx(HalfSrcTy),
                               HalfSrcTySize),
               getValueMapping(getAccPartialMappingIdx(HalfSrcTy),
                               HalfSrcTySize),
               getValueMapping(getAccPartialMappingIdx(SrcTy),
                               SrcTy.getSizeInBits())}),
          /*NumOperands*/ 3);
    }

    auto IsUnmergeUsedByAcc = [&](const MachineInstr *UnmergeMI) -> bool {
      return any_of(MI.defs(), [&](const MachineOperand &MO) {
        auto RegBank = getPreferredRegBankForVectorTy(MRI, TRI, MO.getReg());
        return RegBank && *RegBank == &AIE2P::AccRegBank;
      });
    };

    if (SrcTy.getSizeInBits() == 1024) {
      if (RB == &AIE2P::AccRegBank || IsUnmergeUsedByAcc(&MI)) {
        return getInstructionMapping(
            /*ID*/ 1, /*Cost*/ 1,
            getOperandsMapping(
                {getValueMapping(getAccPartialMappingIdx(HalfSrcTy),
                                 HalfSrcTySize),
                 getValueMapping(getAccPartialMappingIdx(HalfSrcTy),
                                 HalfSrcTySize),
                 getValueMapping(getAccPartialMappingIdx(SrcTy),
                                 SrcTy.getSizeInBits())}),
            /*NumOperands*/ 3);
      } else {
        return getInstructionMapping(
            /*ID*/ 1, /*Cost*/ 1,
            getOperandsMapping(
                {getValueMapping(getVecPartialMappingIdx(HalfSrcTy),
                                 HalfSrcTySize),
                 getValueMapping(getVecPartialMappingIdx(HalfSrcTy),
                                 HalfSrcTySize),
                 getValueMapping(getVecPartialMappingIdx(SrcTy),
                                 SrcTy.getSizeInBits())}),
            /*NumOperands*/ 3);
      }
    }

    if (SrcTy.getSizeInBits() == 512) {
      return getInstructionMapping(
          /*ID*/ 1, /*Cost*/ 1,
          getOperandsMapping({getValueMapping(PMI_VREG256, 256),
                              getValueMapping(PMI_VREG256, 256),
                              getValueMapping(PMI_VREG512, 512)}),
          /*NumOperands*/ 3);
    }
    return AIEBaseRegisterBankInfo::getInstrMapping(MI);
  }
  case TargetOpcode::G_CONCAT_VECTORS: {
    // Check if G_CONCAT_VECTORS feeds acc instructions.
    Register DstReg = MI.getOperand(0).getReg();
    LLT DstType = MRI.getType(DstReg);

    // 512-bit concats can only be supported on the vector regbank
    if (DstType.getSizeInBits() == 512) {
      for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
        LLT Type = MRI.getType(MI.getOperand(Idx).getReg());
        OpRegBankIdx[Idx] = getVecPartialMappingIdx(Type);
      }
      return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                           OpRegBankIdx);
    }
    auto PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
    if (PreferredRegBank && &AIE2P::AccRegBank == *PreferredRegBank) {
      OpRegBankIdx[0] = getAccPartialMappingIdx(DstType);
      for (unsigned Idx = 1; Idx < NumOperands; ++Idx) {
        LLT Type = MRI.getType(MI.getOperand(Idx).getReg());
        OpRegBankIdx[Idx] = getAccPartialMappingIdx(Type);
      }
      return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                           OpRegBankIdx);
    }
    return AIEBaseRegisterBankInfo::getInstrMapping(MI);
  }
  case TargetOpcode::G_LOAD:
  case AIE2P::G_AIE_OFFSET_LOAD:
  case AIE2P::G_AIE_POSTINC_LOAD:
  case AIE2P::G_AIE_POSTINC_2D_LOAD:
  case AIE2P::G_AIE_POSTINC_3D_LOAD: {
    bool isAccRegMapping = false;
    bool isFifoPhysRegMapping = false;

    // Check if that load feeds acc or fifo instructions.
    Register UseCandidate = MI.getOperand(0).getReg();
    LLT Type = MRI.getType(UseCandidate);

    MachineMemOperand *MMO = *MI.memoperands_begin();
    const unsigned MemSize = 8 * MMO->getSize().getValue();
    // Size of accumulator and fifo vectors on aie2p >= 512.
    // for MemSize < 512, fallback to base instruction mapping.
    if (MemSize < 512)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    // Check if we already know the register bank.
    auto *RB = getRegBank(UseCandidate, MRI, TRI);
    if (RB == &AIE2P::AccRegBank || RB == &AIE2P::FifoRegBank ||
        RB == &AIE2P::VRegBank)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);
    auto PreferredRegBank =
        getPreferredRegBankForVectorTy(MRI, TRI, UseCandidate);

    PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, UseCandidate);
    if (PreferredRegBank && &AIE2P::AccRegBank == *PreferredRegBank)
      isAccRegMapping = true;
    else if (PreferredRegBank && &AIE2P::FifoRegBank == *PreferredRegBank)
      isFifoPhysRegMapping = true;

    // First source Idx (pointer reg)
    const unsigned FirstSrcIdx = MI.getNumExplicitDefs();

    if (isAccRegMapping || isFifoPhysRegMapping) {
      // Determine the appropriate mapping index
      const unsigned MappingIdx = isAccRegMapping
                                      ? getAccPartialMappingIdx(Type)
                                      : getFifoPartialMappingIdx(Type);

      // Set all operand mapping indices to PMI_MOD by default.
      // Set all operand sizes to 20 by default.
      OpSize.assign(NumOperands, 20);
      OpRegBankIdx.assign(NumOperands, PMI_MOD);
      // Set up vector operand indices
      OpRegBankIdx[0] =
          static_cast<AIEBaseRegisterBankInfo::PartialMappingIdx>(MappingIdx);
      // Assign PMI_PTR and PMI_MOD based on FirstSrcIdx
      for (unsigned I = 1; I < FirstSrcIdx; ++I) {
        OpRegBankIdx[I] = (I == 1) ? PMI_PTR : PMI_MOD;
      }
      // Assign PMI_PTR at FirstSrcIdx
      OpRegBankIdx[FirstSrcIdx] = PMI_PTR;
      return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                           OpRegBankIdx);
    }
    return AIEBaseRegisterBankInfo::getInstrMapping(MI);
  }
  case TargetOpcode::G_STORE:
  case AIE2P::G_AIE_OFFSET_STORE:
  case AIE2P::G_AIE_POSTINC_STORE:
  case AIE2P::G_AIE_POSTINC_2D_STORE:
  case AIE2P::G_AIE_POSTINC_3D_STORE: {
    // Select the operand index for VecReg.
    const unsigned VecRegOpIdx = MI.getNumExplicitDefs();
    Register VecReg = MI.getOperand(VecRegOpIdx).getReg();
    // Size of accumulator and fifo vectors on aie2p >= 512.
    // for VecSize < 512, fallback to base instruction mapping.
    if (MRI.getType(VecReg).getSizeInBits() < 512)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    auto *DefRegBank = getRegBank(VecReg, MRI, TRI);
    // Only process if VecReg is defined in Accumulator or Fifo register banks.
    if (DefRegBank != &AIE2P::AccRegBank && DefRegBank != &AIE2P::FifoRegBank)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    // Compute the partial mapping index based on the register bank.
    const unsigned MappingIdx =
        (DefRegBank == &AIE2P::AccRegBank)
            ? getAccPartialMappingIdx(MRI.getType(VecReg))
            : getFifoPartialMappingIdx(MRI.getType(VecReg));

    // Set all operand mapping indices to PMI_MOD by default.
    // Set all operand sizes to 20 by default.
    OpSize.assign(NumOperands, 20);
    OpRegBankIdx.assign(NumOperands, PMI_MOD);

    // Initialize first few indices based on VRegOpIdx
    for (unsigned I = 0; I < VecRegOpIdx; ++I) {
      OpRegBankIdx[I] = (I == 0) ? PMI_PTR : PMI_MOD;
    }
    OpRegBankIdx[VecRegOpIdx] =
        static_cast<AIEBaseRegisterBankInfo::PartialMappingIdx>(MappingIdx);

    // Assign PMI_PTR to the next operand if within bounds
    assert(((VecRegOpIdx + 1) < NumOperands) && "RegOpIdx + 1 out of bounds");
    OpRegBankIdx[VecRegOpIdx + 1] = PMI_PTR;

    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  default:
    // Base class implementation for others
    return AIEBaseRegisterBankInfo::getInstrMapping(MI);
  }

  return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                       OpRegBankIdx);
}

void AIE2PRegisterBankInfo::setAIEGenericInstrMapping(
    const MachineInstr &MI, SmallVector<unsigned, 4> &OpSize,
    SmallVector<PartialMappingIdx, 4> &OpRegBankIdx) const {
  const MachineFunction &MF = *MI.getParent()->getParent();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  switch (MI.getOpcode()) {
  case AIE2P::G_AIE_OFFSET_STORE:
  case AIE2P::G_AIE_OFFSET_LOAD:
  case AIE2P::G_AIE_OFFSET_ZEXTLOAD:
  case AIE2P::G_AIE_OFFSET_SEXTLOAD: {
    // Offset is operand #2
    OpRegBankIdx[2] = PMI_MOD;
    break;
  }
  case AIE2P::G_AIE_POSTINC_STORE:
  case AIE2P::G_AIE_POSTINC_LOAD:
  case AIE2P::G_AIE_POSTINC_ZEXTLOAD:
  case AIE2P::G_AIE_POSTINC_SEXTLOAD: {
    // Offset is operand #3
    OpRegBankIdx[3] = PMI_MOD;
    break;
  }
  case AIE2P::G_AIE_UNPAD_VECTOR:
  case AIE2P::G_AIE_PAD_VECTOR_UNDEF: {
    // Pad/Unpad typically pads/discards 128-/256-bit, which is only supported
    // on the vector register bank
    Register SrcReg0 = MI.getOperand(1).getReg();
    Register DstReg = MI.getOperand(0).getReg();
    LLT SrcType0 = MRI.getType(SrcReg0);
    LLT DstType = MRI.getType(DstReg);
    OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType0);
    break;
  }
  case AIE2P::G_AIE_ADD_VECTOR_ELT_HI: {
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(1).getReg();
    LLT DstType = MRI.getType(DstReg);
    LLT SrcType0 = MRI.getType(SrcReg0);
    assert(DstType.getSizeInBits() == 512 &&
           "Unsupported vector size for G_AIE_ADD_VECTOR_ELT_HI!");
    OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType0);
    break;
  }
  case AIE2P::G_AIE_BROADCAST_VECTOR: {
    Register DstReg = MI.getOperand(0).getReg();
    LLT DstType = MRI.getType(DstReg);
    unsigned Size = DstType.getSizeInBits();
    // 512-bit size is supported using VBCST and 2048-bit using VCLR
    assert((Size == 512 || Size == 2048) &&
           "Unsupported vector size for G_AIE_BROADCAST_VECTOR!");
    if (Size == 2048)
      OpRegBankIdx[0] = getAccPartialMappingIdx(DstType);
    else
      OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    break;
  }

  case AIE2P::G_AIE_INSERT_VECTOR_ELT: {
    LLT DstType = MRI.getType(MI.getOperand(0).getReg());
    LLT SrcType = MRI.getType(MI.getOperand(1).getReg());
    assert(DstType == SrcType);
    OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType);
    break;
  }
  }
}

const RegisterBank &
AIE2PRegisterBankInfo::getRegBankFromRegClass(const TargetRegisterClass &RC,
                                              LLT Ty) const {
  const auto &GPRs = getRegBank(AIE2P::GPRRegBankID);
  const auto &PTRs = getRegBank(AIE2P::PTRRegBankID);
  const auto &MODs = getRegBank(AIE2P::MODRegBankID);
  const auto &VECs = getRegBank(AIE2P::VRegBankID);
  const auto &ACCs = getRegBank(AIE2P::AccRegBankID);
  const auto &FIFOs = getRegBank(AIE2P::FifoRegBankID);

  switch (RC.getID()) {
  case AIE2P::eRRegClassID:
  case AIE2P::mSsRegClassID:
  case AIE2P::eR26RegClassID:
  case AIE2P::eR27RegClassID:
  case AIE2P::eR28RegClassID:
  case AIE2P::eR29RegClassID:
  case AIE2P::eLRegClassID:
  case AIE2P::eSRegClassID:
  case AIE2P::mS2RegClassID:
  case AIE2P::mS3RegClassID:
  case AIE2P::eERegClassID:
  case AIE2P::EXPVEC64RegClassID:
  case AIE2P::EXPVEC64_with_sub_hi_exp_in_eEheRegClassID:
  case AIE2P::EXPVEC64_with_sub_hi_exp_in_eEhoRegClassID:
    return GPRs;
  case AIE2P::ePRegClassID:
  case AIE2P::eSpecial20RegClassID:
  case AIE2P::eSpecial20_as_32BitRegClassID:
  case AIE2P::eSPRegClassID:
  case AIE2P::eSP_as_32BitRegClassID:
  case AIE2P::mSPmRegClassID:
    return PTRs;
  case AIE2P::eMRegClassID:
  case AIE2P::eM_as_32BitRegClassID:
  case AIE2P::eDNRegClassID:
  case AIE2P::eDN_as_32BitRegClassID:
  case AIE2P::eDJRegClassID:
  case AIE2P::eDJ_as_32BitRegClassID:
  case AIE2P::eDCRegClassID:
  case AIE2P::eDC_as_32BitRegClassID:
    return MODs;
  case AIE2P::VEC128RegClassID:
  case AIE2P::VEC256RegClassID:
  case AIE2P::VEC512RegClassID:
  case AIE2P::VEC1024RegClassID:
    return VECs;
  case AIE2P::ACC512RegClassID:
  case AIE2P::ACC1024RegClassID:
  case AIE2P::ACC2048RegClassID:
  case AIE2P::mDMaRegClassID:
    return ACCs;
  case AIE2P::FIFO512RegClassID:
  case AIE2P::FIFO1024RegClassID:
    return FIFOs;
  default:
    if (GPRs.covers(RC)) {
      return GPRs;
    }
    if (PTRs.covers(RC)) {
      return PTRs;
    }
    if (MODs.covers(RC)) {
      return MODs;
    }
    if (VECs.covers(RC)) {
      return VECs;
    }
    if (ACCs.covers(RC)) {
      return ACCs;
    }
    if (FIFOs.covers(RC)) {
      return FIFOs;
    }
    dbgs() << "ID: " << RC.getID() << "\n";
    llvm_unreachable("Register class not supported");
  }
}

void AIE2PRegisterBankInfo::applyMappingImpl(
    MachineIRBuilder &Builder, const OperandsMapper &OpdMapper) const {
  switch (OpdMapper.getMI().getOpcode()) {
  case TargetOpcode::G_BITCAST:
    // Those ID must match getInstrAlternativeMappings.
    assert((OpdMapper.getInstrMapping().getID() >= 1 &&
            OpdMapper.getInstrMapping().getID() <= 4) &&
           "Don't know how to handle that ID");
    return applyDefaultMapping(OpdMapper);
  default:
    break;
  }
  AIEBaseRegisterBankInfo::applyMappingImpl(Builder, OpdMapper);
}
